mapper.select:
select count(*) from vm_device_iot_rel_t t
where t.device_code = #{param.deviceCode}

and t.iot_device_code = #{param.iotDeviceCode}

and t.delete_flag = '0' and t.bind_flag = '0'
and t.industry_code = #{param.industryCode} and t.tenant_id = #{param.tenantId}

select t.device_code deviceCode, t.iot_device_code iotDeviceCode from vm_device_iot_rel_t t where t.delete_flag = '0' and t.bind_flag = '0'
and t.device_code = #{param.deviceCode}
and t.iot_device_code = #{param.iotDeviceCode}

select count(*) from vm_device_iot_rel_t t
where t.device_code = #{param.deviceCode}
    and t.delete_flag = '0'
    and t.industry_code = #{param.industryCode} and t.tenant_id = #{param.tenantId}
